Object.assign(zhLabels,{'Customer session restored. Continue with the pending OTP; do not establish another context.':'客户会话已恢复，请继续验证待处理验证码，无需重新建立会话。','Customer session changed or expired. Sign in and establish a valid context, then explicitly request a fresh OTP.':'客户会话已更改或过期。请登录并建立有效会话，再主动请求新验证码。','OTP expired. Request a fresh OTP in this valid context; do not reuse the old code.':'验证码已过期。请在此有效会话中请求新验证码，不要重复使用旧验证码。','OTP is incorrect. Check the code for this pending request. Attempts remain limited; no automatic retry.':'验证码不正确。请核对当前请求的验证码，尝试次数有限，不会自动重试。','Enter the eight-digit OTP exactly, including any leading zero.':'请输入完整的八位数字验证码，包括开头的零。','This OTP is used, locked or no longer bound to this context. Request a fresh OTP or ask QY for assistance.':'此验证码已使用、已锁定或不再属于当前会话。请请求新验证码或联系 QY 协助。','A pending OTP already exists. Use that code; no additional OTP was requested.':'已有待处理验证码，请使用该验证码；未请求其他验证码。','No pending OTP in this context. Explicitly request a fresh OTP.':'当前会话没有待处理验证码，请主动请求新验证码。','Customer verification could not be resumed. Check the local server and ask QY for assistance; no OTP was submitted.':'无法恢复客户验证，请检查本地服务器并联系 QY 协助；未提交验证码。','Verification result is unknown. Resume the existing context to check it; do not automatically resubmit.':'验证结果未知。请恢复现有会话以检查结果，不要自动再次提交。'});
Object.assign(zhLabels,{'QY session active for reading. Sign in again before recording changes; the page does not store your CSRF credential.':'QY 会话仍可读取资料。记录更改前请重新登录；页面不会储存 CSRF 凭据。','QY authenticated for reading and changes.':'QY 已登录，可读取及记录更改。','QY sign-in required. No session-expiry conclusion can be drawn from an old warning.':'请登录 QY。旧提示不能证明会话已过期。','QY authorization failed or expired. Sign in again; no automatic retry.':'QY 授权失败或已过期。请重新登录，不会自动重试。','Report-contact challenge is expired, unavailable or already handled. Check its state; do not automatically resend.':'报告接收验证请求已过期、不可用或已处理。请检查状态，不要自动重发。','Report-contact instructions loaded. Record simulated manual delivery before the customer confirms.':'已读取报告接收验证指引。请先记录模拟人工发送，再由客户验证。','Report-contact challenge restored. Continue the existing manual verification; no new challenge requested.':'已恢复报告接收验证请求。请继续现有人工验证，未请求新验证码。','Report-contact challenge expired. Ask QY to review before requesting a fresh challenge.':'报告接收验证请求已过期。请求新验证码前请先联系 QY 核实。'});
const originalText=new WeakMap();
function translateText(value){
 if(uiLanguage!=='zh-CN')return value;
 if(Object.prototype.hasOwnProperty.call(zhLabels,value))return zhLabels[value];
 const accountPrefix='Account OTP request ID: ';if(value.startsWith(accountPrefix))return zhLabels[accountPrefix]+value.slice(accountPrefix.length);
 const record=value.match(/^(.*) — ([A-Za-z]+) — revision (\d+)$/);if(record)return record[1]+' — '+(zhLabels[record[2]]||record[2])+' — 版本 '+record[3];
 const prefix='Give QY this report-contact challenge ID: ';if(value.startsWith(prefix))return '请向 QY 提供此报告接收验证请求 ID：'+value.slice(prefix.length).replace('. Local synthetic delivery only.','。仅限本地模拟发送。');
 return value;
}
function displayJSON(value){if(uiLanguage!=='zh-CN')return value;try{const data=JSON.parse(value);const enums=new Set(['state','report_state','channel','reportChannel','calculationGender','birthTimePrecision','purpose','kind','delivery','verificationStatus']);function convert(v,key){if(Array.isArray(v))return v.map(x=>convert(x,key));if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[zhLabels[k]||k,convert(x,k)]));return enums.has(key)&&typeof v==='string'?(zhLabels[v]||v):v;}return JSON.stringify(convert(data,''),null,2);}catch{return value;}}
function applyLanguage(){
 document.documentElement.lang=uiLanguage;
 const walk=document.createTreeWalker(document.documentElement,NodeFilter.SHOW_TEXT);let node;
 while(node=walk.nextNode()){if(['SCRIPT','STYLE'].includes(node.parentElement?.tagName)||node.parentElement?.closest('[data-language-control],[data-no-i18n]'))continue;const previous=originalText.get(node);let original=node.nodeValue;if(previous&&original===previous.rendered)original=previous.original;const trim=original.trim();const rendered=node.parentElement?.closest('pre')?displayJSON(original):original.replace(trim,translateText(trim));originalText.set(node,{original,rendered});if(node.nodeValue!==rendered)node.nodeValue=rendered;}
 for(const item of document.querySelectorAll('[data-language]')){item.setAttribute('aria-pressed',String(item.dataset.language===uiLanguage));}
 for(const item of document.querySelectorAll('[data-i18n-label]'))item.setAttribute('aria-label',translateText(item.dataset.i18nLabel));
 for(const item of document.querySelectorAll('[data-i18n-alt]'))item.setAttribute('alt',translateText(item.dataset.i18nAlt));
 for(const field of document.querySelectorAll('input,select,textarea'))field.setCustomValidity('');
}
function chooseLanguage(language,persist=true){uiLanguage=language==='zh-CN'?'zh-CN':'en';if(qy)renderInvitationBase();if(persist)try{localStorage.setItem('qy-consultation-language',uiLanguage);}catch{}applyLanguage();}
const localizedPrompt=message=>window.prompt(translateText(message));
const localizedConfirm=message=>window.confirm(translateText(message));
for(const item of document.querySelectorAll('[data-language]'))item.addEventListener('click',()=>chooseLanguage(item.dataset.language));
window.addEventListener('storage',event=>{if(event.key==='qy-consultation-language')chooseLanguage(event.newValue,false);});
document.addEventListener('invalid',event=>{const field=event.target;const v=field.validity;if(!v)return;const message=v.valueMissing?(field.type==='checkbox'?'Please select this required acknowledgement.':'Please complete this required field.'):v.patternMismatch?'Please use the requested format.':v.rangeUnderflow||v.rangeOverflow?'Please enter a value within the allowed range.':v.tooShort||v.tooLong?'Please check the required length.':'Please enter a valid value.';field.setCustomValidity(translateText(message));},true);
document.addEventListener('input',event=>{event.target.setCustomValidity?.('');});
document.addEventListener('change',event=>{event.target.setCustomValidity?.('');});
