let pricingBusy=false,currentInvitationPrice=null;
function renderInvitationBase(){if(!currentInvitationPrice)return;const p=currentInvitationPrice,zh=uiLanguage==='zh-CN';el('invitation-base').textContent=(zh?'原价：':'Regular price: ')+price(p.regularPriceSen,'MYR')+' | '+(zh?'适用售价：':'Applicable selling price: ')+price(p.sellingPriceSen,'MYR');}
